<?php require_once __DIR__.'/../services/MercadoPago.php';$u=require_auth();$b=body_json();$plan=get_plan_live((string)($b['planId']??''));if(!$plan)json_response(['error'=>'Plano inválido'],400);$id='ord_'.date('YmdHis').'_'.bin2hex(random_bytes(4));$o=['id'=>$id,'username'=>$u['username'],'email'=>$u['email']??'','planId'=>$plan['id'],'planName'=>$plan['name'],'days'=>$plan['days'],'price'=>$plan['price'],'description'=>'Plano ConnectPlus '.$plan['name'],'status'=>'pending','createdAt'=>date('c')];try{$pay=mp_create_pix($o);$o=array_merge($o,$pay);save_order($o);json_response(['ok'=>true,'order'=>$o]);}catch(Throwable $e){$o['paymentError']=$e->getMessage();save_order($o);json_response(['error'=>$e->getMessage(),'order'=>$o],503);}
